import { BLOB_RADIUS, RULES, TREE_REACH } from '../sim/world';
import { mulberry32 } from '../sim/rng';
import type { Blob, SimEvent, Tree, World } from '../sim/types';

export interface Camera {
  yaw: number;
  tilt: number;
  zoom: number;
}

export interface Pick {
  kind: 'blue' | 'red' | 'tree';
  id: number;
}

interface Proj {
  cx: number;
  cy: number;
  s: number;
  cosY: number;
  sinY: number;
  st: number;
  ct: number;
}

interface BlobVis {
  x: number;
  z: number;
  hop: number;
  phase: number;
  heading: number;
  squash: number;
  glow: number;
  glowColor: string;
  blinkT: number;
  blink: number;
  look: number;
  seen: boolean;
}

interface TreeVis {
  wobble: number;
  slots: number[];
  seen: boolean;
}

type ParticleKind = 'spark' | 'text' | 'ring' | 'puff' | 'heart';

interface Particle {
  kind: ParticleKind;
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  vz: number;
  life: number;
  max: number;
  color: string;
  text?: string;
  size: number;
}

interface Decor {
  x: number;
  z: number;
  kind: 'tuft' | 'flower' | 'pebble';
  hue: number;
}

interface Hit {
  kind: Pick['kind'];
  id: number;
  sx: number;
  sy: number;
  r: number;
}

const TAU = Math.PI * 2;
const WALL_H = 1.1;
const BLUE = { base: '#3f8ffb', light: '#d3eaff', dark: '#1d4cad', glow: '120,200,255' };
const RED = { base: '#ff5a5f', light: '#ffd0cc', dark: '#a81f30', glow: '255,140,140' };
const FLOWER_COLORS = ['#ff9ecb', '#ffe27a', '#c9a4ff', '#ffffff'];

function clamp(v: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, v));
}

function angDiff(a: number, b: number): number {
  let d = a - b;
  while (d > Math.PI) d -= TAU;
  while (d < -Math.PI) d += TAU;
  return d;
}

function mixRgb(a: [number, number, number], b: [number, number, number], t: number): string {
  const r = Math.round(a[0] + (b[0] - a[0]) * t);
  const g = Math.round(a[1] + (b[1] - a[1]) * t);
  const bl = Math.round(a[2] + (b[2] - a[2]) * t);
  return `rgb(${r},${g},${bl})`;
}

const WALL_DARK: [number, number, number] = [112, 74, 43];
const WALL_LIT: [number, number, number] = [226, 176, 112];

/**
 * Pseudo-3D renderer for the garden dish. World space is x/z on the ground with y up.
 * Yaw spins the dish, tilt sets the camera elevation. Everything is painted back to front.
 */
export class WorldRenderer {
  private vis = new Map<number, BlobVis>();
  private treeVis = new Map<number, TreeVis>();
  private particles: Particle[] = [];
  private decor: Decor[] = [];
  private decorKey = '';
  private hits: Hit[] = [];
  private world: World | null = null;
  private time = 0;

  reset(): void {
    this.vis.clear();
    this.treeVis.clear();
    this.particles = [];
  }

  pick(x: number, y: number): Pick | null {
    let best: Hit | null = null;
    let bestScore = Infinity;
    for (const h of this.hits) {
      const d = Math.hypot(h.sx - x, h.sy - y);
      if (d > h.r) continue;
      const score = d / h.r + (h.kind === 'tree' ? 0.25 : 0);
      if (score < bestScore) {
        bestScore = score;
        best = h;
      }
    }
    return best ? { kind: best.kind, id: best.id } : null;
  }

  draw(
    ctx: CanvasRenderingContext2D,
    W: number,
    H: number,
    world: World,
    cam: Camera,
    dt: number,
    selected: Pick | null,
    hovered: Pick | null,
  ): void {
    if (world !== this.world) {
      this.world = world;
      this.reset();
    }
    this.time += dt;
    this.hits = [];
    this.ensureDecor(world);

    const P = this.projection(W, H, world, cam);
    this.drawBackground(ctx, W, H);
    this.drawDishShadow(ctx, P, world);
    this.drawWall(ctx, P, world);
    this.drawTop(ctx, P, world);
    this.drawDecor(ctx, P);

    this.consumeEvents(world, dt);
    this.updateVisuals(world, dt);

    const items: { d: number; draw: () => void }[] = [];
    const shadows: (() => void)[] = [];

    for (const t of world.trees) {
      const tv = this.treeVis.get(t.id);
      if (!tv) continue;
      const base = this.project(P, t.x, 0, t.z);
      shadows.push(() => this.drawGroundDisc(ctx, P, t.x, t.z, 1.7, 'rgba(60,80,30,0.22)'));
      const center = this.project(P, t.x, 2.6, t.z);
      items.push({ d: center.d, draw: () => this.drawTree(ctx, P, t, tv, base, center) });
    }

    for (const b of world.blue) this.addBlob(ctx, P, world, b, items, shadows, selected, hovered);
    for (const r of world.red) this.addBlob(ctx, P, world, r, items, shadows, selected, hovered);

    for (const s of shadows) s();

    items.sort((a, b) => a.d - b.d);
    for (const it of items) it.draw();

    this.drawSelectionRange(ctx, P, world, selected);
    this.drawParticles(ctx, P, dt);
  }

  // ---------- projection ----------

  private projection(W: number, H: number, world: World, cam: Camera): Proj {
    const R = world.params.worldSize;
    const st = Math.sin(cam.tilt);
    const ct = Math.cos(cam.tilt);
    const s = Math.min((W * 0.44) / R, (H * 0.86) / (R * 2 * st + 3.4 * ct)) * cam.zoom;
    return {
      cx: W / 2,
      cy: H / 2 - (WALL_H * ct * 0.5 - 0.6 * ct) * s,
      s,
      cosY: Math.cos(cam.yaw),
      sinY: Math.sin(cam.yaw),
      st,
      ct,
    };
  }

  private project(P: Proj, x: number, y: number, z: number): { sx: number; sy: number; d: number } {
    const xr = x * P.cosY - z * P.sinY;
    const zr = x * P.sinY + z * P.cosY;
    return {
      sx: P.cx + xr * P.s,
      sy: P.cy + (zr * P.st - y * P.ct) * P.s,
      d: zr * P.ct + y * P.st,
    };
  }

  /** Depth of a world point after rotation (used for painter ordering). */
  private depth(P: Proj, x: number, y: number, z: number): number {
    const zr = x * P.sinY + z * P.cosY;
    return zr * P.ct + y * P.st;
  }

  // ---------- static scenery ----------

  private ensureDecor(world: World): void {
    const key = `${world.params.seed}:${world.params.worldSize}`;
    if (key === this.decorKey) return;
    this.decorKey = key;
    const rng = mulberry32(world.params.seed ^ 0x5bd1e995);
    const R = world.params.worldSize;
    this.decor = [];
    const count = Math.round(R * 6);
    for (let i = 0; i < count; i++) {
      const a = rng() * TAU;
      const d = Math.sqrt(rng()) * R * 0.92;
      const roll = rng();
      const kind: Decor['kind'] = roll < 0.5 ? 'tuft' : roll < 0.8 ? 'flower' : 'pebble';
      this.decor.push({ x: Math.cos(a) * d, z: Math.sin(a) * d, kind, hue: rng() });
    }
  }

  private drawBackground(ctx: CanvasRenderingContext2D, W: number, H: number): void {
    const g = ctx.createLinearGradient(0, 0, 0, H);
    g.addColorStop(0, '#e9f6ff');
    g.addColorStop(0.55, '#fff6e6');
    g.addColorStop(1, '#ffe9d2');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, W, H);
    // soft confetti dots for a little toy-box feel
    ctx.fillStyle = 'rgba(255,255,255,0.45)';
    for (let i = 0; i < 26; i++) {
      const x = ((i * 137.5) % 100) / 100;
      const y = ((i * 61.3) % 100) / 100;
      ctx.beginPath();
      ctx.arc(x * W, y * H, 2 + (i % 3), 0, TAU);
      ctx.fill();
    }
  }

  private drawDishShadow(ctx: CanvasRenderingContext2D, P: Proj, world: World): void {
    const R = world.params.worldSize;
    const c = this.project(P, 0, -WALL_H - 0.2, 0);
    const g = ctx.createRadialGradient(c.sx, c.sy, R * P.s * 0.2, c.sx, c.sy, R * P.s * 1.1);
    g.addColorStop(0, 'rgba(120,80,40,0.25)');
    g.addColorStop(1, 'rgba(120,80,40,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.ellipse(c.sx, c.sy, R * P.s * 1.1, R * P.s * P.st * 1.1, 0, 0, TAU);
    ctx.fill();
  }

  private drawWall(ctx: CanvasRenderingContext2D, P: Proj, world: World): void {
    const R = world.params.worldSize;
    const N = 120;
    for (let i = 0; i < N; i++) {
      const a0 = (i / N) * TAU;
      const a1 = ((i + 1) / N) * TAU;
      const am = (a0 + a1) / 2;
      const nx = Math.cos(am);
      const nz = Math.sin(am);
      const facing = nx * P.sinY + nz * P.cosY;
      if (facing <= 0) continue;
      const t0 = this.project(P, R * Math.cos(a0), 0, R * Math.sin(a0));
      const t1 = this.project(P, R * Math.cos(a1), 0, R * Math.sin(a1));
      const b1 = this.project(P, R * Math.cos(a1), -WALL_H, R * Math.sin(a1));
      const b0 = this.project(P, R * Math.cos(a0), -WALL_H, R * Math.sin(a0));
      ctx.fillStyle = mixRgb(WALL_DARK, WALL_LIT, Math.pow(facing, 0.8));
      ctx.beginPath();
      ctx.moveTo(t0.sx, t0.sy);
      ctx.lineTo(t1.sx, t1.sy);
      ctx.lineTo(b1.sx, b1.sy);
      ctx.lineTo(b0.sx, b0.sy);
      ctx.closePath();
      ctx.fill();
    }
  }

  private drawTop(ctx: CanvasRenderingContext2D, P: Proj, world: World): void {
    const R = world.params.worldSize;
    const c = this.project(P, 0, 0, 0);
    const g = ctx.createRadialGradient(c.sx, c.sy, 0, c.sx, c.sy, R * P.s);
    g.addColorStop(0, '#d9f8b8');
    g.addColorStop(0.6, '#a6e083');
    g.addColorStop(1, '#84c964');
    ctx.fillStyle = g;
    ctx.beginPath();
    this.ellipsePath(ctx, P, R, 0, 160);
    ctx.fill();

    // rim highlight and soil ring
    ctx.lineWidth = Math.max(2, 0.16 * P.s);
    ctx.strokeStyle = '#f3d19b';
    ctx.beginPath();
    this.ellipsePath(ctx, P, R, 0, 160);
    ctx.stroke();

    ctx.lineWidth = 1;
    ctx.strokeStyle = 'rgba(70,120,50,0.22)';
    for (const f of [0.35, 0.7]) {
      ctx.beginPath();
      this.ellipsePath(ctx, P, R * f, 0, 120);
      ctx.stroke();
    }
  }

  private ellipsePath(ctx: CanvasRenderingContext2D, P: Proj, r: number, y: number, n: number): void {
    for (let i = 0; i <= n; i++) {
      const a = (i / n) * TAU;
      const p = this.project(P, Math.cos(a) * r, y, Math.sin(a) * r);
      if (i === 0) ctx.moveTo(p.sx, p.sy);
      else ctx.lineTo(p.sx, p.sy);
    }
    ctx.closePath();
  }

  private drawDecor(ctx: CanvasRenderingContext2D, P: Proj): void {
    for (const d of this.decor) {
      const p = this.project(P, d.x, 0, d.z);
      const k = P.s / 22;
      if (d.kind === 'tuft') {
        ctx.strokeStyle = 'rgba(60,120,50,0.5)';
        ctx.lineWidth = 1.6;
        ctx.beginPath();
        for (const dx of [-3, 0, 3]) {
          ctx.moveTo(p.sx + dx * k, p.sy);
          ctx.lineTo(p.sx + (dx * 1.4 + (d.hue - 0.5) * 2) * k, p.sy - (5 + d.hue * 3) * k);
        }
        ctx.stroke();
      } else if (d.kind === 'flower') {
        const col = FLOWER_COLORS[Math.floor(d.hue * FLOWER_COLORS.length)];
        ctx.fillStyle = col;
        for (let i = 0; i < 5; i++) {
          const a = (i / 5) * TAU;
          ctx.beginPath();
          ctx.arc(p.sx + Math.cos(a) * 2.6 * k, p.sy - 4 * k + Math.sin(a) * 2.6 * k, 2.2 * k, 0, TAU);
          ctx.fill();
        }
        ctx.fillStyle = '#ffd34d';
        ctx.beginPath();
        ctx.arc(p.sx, p.sy - 4 * k, 1.8 * k, 0, TAU);
        ctx.fill();
      } else {
        ctx.fillStyle = 'rgba(150,140,130,0.6)';
        ctx.beginPath();
        ctx.ellipse(p.sx, p.sy, 3.5 * k, 2.2 * k, 0, 0, TAU);
        ctx.fill();
      }
    }
  }

  private drawGroundDisc(
    ctx: CanvasRenderingContext2D,
    P: Proj,
    x: number,
    z: number,
    r: number,
    fill: string,
  ): void {
    const c = this.project(P, x, 0, z);
    ctx.fillStyle = fill;
    ctx.beginPath();
    ctx.ellipse(c.sx, c.sy, r * P.s, r * P.s * P.st, 0, 0, TAU);
    ctx.fill();
  }

  // ---------- events and smoothing ----------

  private consumeEvents(world: World, dt: number): void {
    const events: SimEvent[] = world.events.splice(0, world.events.length);
    const cap = 80;
    for (let i = 0; i < events.length && i < cap; i++) this.applyEvent(events[i], world);
    for (let i = 0; i < this.particles.length; i++) {
      const p = this.particles[i];
      p.life -= dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.z += p.vz * dt;
      if (p.kind === 'spark') p.vy -= 5 * dt;
    }
    this.particles = this.particles.filter((p) => p.life > 0);
    if (this.particles.length > 500) this.particles.splice(0, this.particles.length - 500);
  }

  private applyEvent(ev: SimEvent, world: World): void {
    if (ev.type === 'eat') {
      const tv = this.treeVis.get(ev.treeId);
      if (tv) tv.wobble = 1;
      const bv = this.vis.get(ev.id);
      if (bv) {
        bv.glow = 1;
        bv.glowColor = '120,230,120';
        bv.squash = 0.6;
      }
      const tree = world.trees.find((t) => t.id === ev.treeId);
      const sx = tree ? tree.x : ev.x;
      const sz = tree ? tree.z : ev.z;
      this.spawnSparks(sx, 2.0, sz, '#8ee04f', 7);
      this.particles.push(this.text(ev.x, 1.9, ev.z, `+${Math.round(ev.gain)}`, '#2f9e44', 1.1));
    } else if (ev.type === 'bite') {
      const rv = this.vis.get(ev.redId);
      const bv = this.vis.get(ev.blueId);
      if (rv) {
        rv.glow = 1;
        rv.glowColor = '255,150,170';
        rv.squash = 0.5;
      }
      if (bv) {
        bv.squash = 1;
        bv.glow = 0.5;
        bv.glowColor = '255,150,170';
      }
      this.spawnHearts(ev.x, 1.4, ev.z, 2);
      this.particles.push(this.text(ev.x, 1.8, ev.z, `+${Math.round(ev.gain)}`, '#d6336c', 1.0));
    } else if (ev.type === 'birth') {
      const col = ev.group === 'blue' ? '#5aa7ff' : '#ff7a7a';
      this.particles.push({
        kind: 'ring',
        x: ev.x,
        y: 0.05,
        z: ev.z,
        vx: 0,
        vy: 0,
        vz: 0,
        life: 0.9,
        max: 0.9,
        color: col,
        size: 0.2,
      });
      this.spawnSparks(ev.x, 1.0, ev.z, col, 6);
    } else if (ev.type === 'death') {
      for (let i = 0; i < 3; i++) {
        this.particles.push({
          kind: 'puff',
          x: ev.x + (Math.random() - 0.5) * 0.4,
          y: 0.5,
          z: ev.z + (Math.random() - 0.5) * 0.4,
          vx: 0,
          vy: 0.8 + Math.random() * 0.4,
          vz: 0,
          life: 0.8,
          max: 0.8,
          color: '120,120,130',
          size: 0.4,
        });
      }
    }
  }

  private text(x: number, y: number, z: number, text: string, color: string, life: number): Particle {
    return { kind: 'text', x, y, z, vx: 0, vy: 0, vz: 0, life, max: life, color, text, size: 1 };
  }

  private spawnSparks(x: number, y: number, z: number, color: string, n: number): void {
    for (let i = 0; i < n; i++) {
      const a = Math.random() * TAU;
      const v = 1 + Math.random() * 1.6;
      this.particles.push({
        kind: 'spark',
        x,
        y,
        z,
        vx: Math.cos(a) * v,
        vy: 2 + Math.random() * 2,
        vz: Math.sin(a) * v,
        life: 0.7 + Math.random() * 0.4,
        max: 1.1,
        color,
        size: 0.5,
      });
    }
  }

  private spawnHearts(x: number, y: number, z: number, n: number): void {
    for (let i = 0; i < n; i++) {
      this.particles.push({
        kind: 'heart',
        x: x + (Math.random() - 0.5) * 0.6,
        y,
        z: z + (Math.random() - 0.5) * 0.6,
        vx: 0,
        vy: 1.4,
        vz: 0,
        life: 1.1,
        max: 1.1,
        color: '#ff5c8a',
        size: 1,
      });
    }
  }

  private updateVisuals(world: World, dt: number): void {
    for (const v of this.vis.values()) v.seen = false;
    for (const t of world.trees) {
      let tv = this.treeVis.get(t.id);
      if (!tv) {
        tv = { wobble: 0, slots: [], seen: false };
        this.treeVis.set(t.id, tv);
      }
      tv.seen = true;
      tv.wobble = Math.max(0, tv.wobble - dt * 2.5);
      while (tv.slots.length < world.params.fruitLimit) tv.slots.push(0);
      for (let k = 0; k < tv.slots.length; k++) {
        const target = k < t.fruit ? 1 : 0;
        tv.slots[k] += (target - tv.slots[k]) * Math.min(1, dt * 9);
      }
    }
    for (const [id, tv] of this.treeVis) if (!tv.seen) this.treeVis.delete(id);

    for (const group of [world.blue, world.red]) {
      for (const b of group) this.updateBlob(b, dt);
    }
    for (const [id, v] of this.vis) if (!v.seen) this.vis.delete(id);
  }

  private updateBlob(b: Blob, dt: number): void {
    let v = this.vis.get(b.id);
    if (!v) {
      v = {
        x: b.x,
        z: b.z,
        hop: 0,
        phase: Math.random() * TAU,
        heading: Math.atan2(b.vz, b.vx) || 0,
        squash: 0,
        glow: 0,
        glowColor: '255,255,255',
        blinkT: 2 + Math.random() * 3,
        blink: 1,
        look: 0,
        seen: true,
      };
      this.vis.set(b.id, v);
    }
    v.seen = true;
    const k = Math.min(1, dt * 14);
    v.x += (b.x - v.x) * k;
    v.z += (b.z - v.z) * k;
    v.phase += dt * (3 + b.moved * 7);
    const walking = Math.min(1, b.moved / 0.5);
    const bob = Math.abs(Math.sin(v.phase));
    const eatingBob = b.action === 'eat' ? Math.sin(this.time * 9 + b.id) * 0.05 : 0;
    const targetHop = b.action === 'pause' ? 0.06 : bob * 0.16 * walking + eatingBob;
    v.hop += (targetHop - v.hop) * Math.min(1, dt * 12);
    if (b.moved > 0.08) {
      const tgt = Math.atan2(b.vz, b.vx);
      v.heading = v.heading + angDiff(tgt, v.heading) * Math.min(1, dt * 6);
    }
    v.squash = Math.max(0, v.squash - dt * 3);
    v.glow = Math.max(0, v.glow - dt * 1.2);
    v.blinkT -= dt;
    if (v.blinkT <= 0) {
      v.blink = 0;
      v.blinkT = 2.4 + Math.random() * 2.6;
    }
    v.blink = Math.min(1, v.blink + dt * 9);
    v.look = b.action === 'hunt' || b.action === 'seek' ? 1 : 0;
  }

  // ---------- drawing objects ----------

  private addBlob(
    ctx: CanvasRenderingContext2D,
    P: Proj,
    world: World,
    b: Blob,
    items: { d: number; draw: () => void }[],
    shadows: (() => void)[],
    selected: Pick | null,
    hovered: Pick | null,
  ): void {
    const v = this.vis.get(b.id);
    if (!v) return;
    const maturity = b.group === 'blue' ? RULES.blueMaturity : RULES.redMaturity;
    const grow = 0.55 + 0.45 * Math.min(1, b.age / maturity);
    const rb = BLOB_RADIUS * grow;
    const sel = selected?.id === b.id && selected.kind === b.group;
    const hov = hovered?.id === b.id && hovered.kind === b.group;

    shadows.push(() => {
      const hopFade = clamp(1 - v.hop * 2.4, 0.35, 1);
      this.drawGroundDisc(ctx, P, v.x, v.z, rb * 1.05 * hopFade, 'rgba(60,50,40,0.22)');
      if (sel || hov) {
        const c = this.project(P, v.x, 0, v.z);
        ctx.strokeStyle = sel ? 'rgba(255,190,40,0.95)' : 'rgba(255,255,255,0.9)';
        ctx.lineWidth = sel ? 3 : 2;
        ctx.beginPath();
        ctx.ellipse(c.sx, c.sy, (rb * 1.45) * P.s, rb * 1.45 * P.s * P.st, 0, 0, TAU);
        ctx.stroke();
      }
    });

    const center = this.project(P, v.x, rb * 0.82 + v.hop, v.z);
    const base = this.project(P, v.x, 0, v.z);
    const d = center.d + 0.001;
    const headingScreen = Math.atan2(
      this.project(P, v.x + Math.cos(v.heading) * 0.5, 0, v.z + Math.sin(v.heading) * 0.5).sy - base.sy,
      this.project(P, v.x + Math.cos(v.heading) * 0.5, 0, v.z + Math.sin(v.heading) * 0.5).sx - base.sx,
    );
    const rpx = rb * P.s;
    this.hits.push({
      kind: b.group,
      id: b.id,
      sx: center.sx,
      sy: center.sy,
      r: Math.max(14, rpx * 1.3),
    });

    items.push({
      d: this.depth(P, v.x, 0, v.z) + 0.001,
      draw: () => this.drawBlob(ctx, b, v, center.sx, center.sy, rpx, headingScreen, grow, hov, sel),
    });
    void d;
    void world;
  }

  private drawBlob(
    ctx: CanvasRenderingContext2D,
    b: Blob,
    v: BlobVis,
    sx: number,
    sy: number,
    rpx: number,
    heading: number,
    grow: number,
    hov: boolean,
    sel: boolean,
  ): void {
    const pal = b.group === 'blue' ? BLUE : RED;
    const stretch = clamp(b.moved / 1.6, 0, 0.3);
    const breathe = 1 + Math.sin(this.time * 2.5 + b.id) * 0.02;
    const sq = v.squash;
    const rx = rpx * (1 + stretch * 0.5 + sq * 0.18) * breathe;
    const ry = rpx * (1 - stretch * 0.3 - sq * 0.2) * breathe * 0.94;

    // glow halo
    if (v.glow > 0.01) {
      const g = ctx.createRadialGradient(sx, sy, rx * 0.6, sx, sy, rx * 2.1);
      g.addColorStop(0, `rgba(${v.glowColor},${0.55 * v.glow})`);
      g.addColorStop(1, `rgba(${v.glowColor},0)`);
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(sx, sy, rx * 2.1, 0, TAU);
      ctx.fill();
    }

    // bean body
    const cosH = Math.cos(heading);
    const sinH = Math.sin(heading);
    ctx.beginPath();
    const N = 48;
    for (let i = 0; i <= N; i++) {
      const th = (i / N) * TAU;
      const dent = 1 - 0.13 * Math.exp(-(angDiff(th, Math.PI) ** 2) / 0.35);
      const lx = Math.cos(th) * rx * dent;
      const ly = Math.sin(th) * ry * dent;
      const px = sx + lx * cosH - ly * sinH;
      const py = sy + lx * sinH + ly * cosH;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
    const g = ctx.createRadialGradient(sx - rx * 0.35, sy - ry * 0.45, rx * 0.1, sx, sy, rx * 1.25);
    g.addColorStop(0, pal.light);
    g.addColorStop(0.35, pal.base);
    g.addColorStop(1, pal.dark);
    ctx.fillStyle = g;
    ctx.fill();
    ctx.lineWidth = Math.max(1.2, rpx * 0.08);
    ctx.strokeStyle = 'rgba(40,30,30,0.35)';
    ctx.stroke();

    // gloss
    ctx.save();
    ctx.translate(sx - rx * 0.36, sy - ry * 0.46);
    ctx.rotate(-0.5);
    ctx.fillStyle = 'rgba(255,255,255,0.6)';
    ctx.beginPath();
    ctx.ellipse(0, 0, rx * 0.26, ry * 0.14, 0, 0, TAU);
    ctx.fill();
    ctx.restore();

    this.drawFace(ctx, b, v, sx + cosH * rx * 0.1, sy + sinH * ry * 0.1 - ry * 0.05, rx, ry, pal);

    if (sel) {
      ctx.strokeStyle = 'rgba(255,190,40,0.95)';
      ctx.lineWidth = 2.5;
      ctx.beginPath();
      ctx.ellipse(sx, sy + ry * 0.15, rx * 1.35, ry * 1.35, 0, 0, TAU);
      ctx.stroke();
    } else if (hov) {
      ctx.strokeStyle = 'rgba(255,255,255,0.9)';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.ellipse(sx, sy + ry * 0.15, rx * 1.3, ry * 1.3, 0, 0, TAU);
      ctx.stroke();
    }
    void grow;
  }

  private drawFace(
    ctx: CanvasRenderingContext2D,
    b: Blob,
    v: BlobVis,
    fx: number,
    fy: number,
    rx: number,
    ry: number,
    _pal: { base: string },
  ): void {
    const eyeOpen = b.action === 'idle' ? 0.45 : 1;
    const wide = b.action === 'flee' ? 1.25 : 1;
    const happy = b.action === 'pause' || (v.glow > 0.2 && b.action !== 'eat');
    const blink = v.blink;
    const look = v.look ? 0.16 : 0;
    const eyeDx = rx * 0.33;
    const eyeY = fy - ry * 0.12;
    const ew = rx * 0.17 * wide;
    const eh = ry * 0.24 * wide * eyeOpen * blink;

    ctx.fillStyle = 'rgba(255,120,140,0.42)';
    ctx.beginPath();
    ctx.ellipse(fx - rx * 0.56, fy + ry * 0.12, rx * 0.13, ry * 0.09, 0, 0, TAU);
    ctx.ellipse(fx + rx * 0.56, fy + ry * 0.12, rx * 0.13, ry * 0.09, 0, 0, TAU);
    ctx.fill();

    for (const side of [-1, 1]) {
      const ex = fx + side * eyeDx;
      if (happy) {
        ctx.strokeStyle = '#2b2233';
        ctx.lineWidth = Math.max(1.6, rx * 0.09);
        ctx.beginPath();
        ctx.arc(ex, eyeY + eh * 0.2, ew * 0.9, Math.PI * 1.1, Math.PI * 1.9);
        ctx.stroke();
      } else {
        ctx.fillStyle = '#fffdf7';
        ctx.beginPath();
        ctx.ellipse(ex, eyeY, ew, Math.max(0.8, eh), 0, 0, TAU);
        ctx.fill();
        ctx.fillStyle = '#2b2233';
        ctx.beginPath();
        ctx.arc(ex + look * rx + (v.look ? 0 : 0), eyeY + eh * 0.12, ew * 0.55, 0, TAU);
        ctx.fill();
      }
    }

    const mouthY = fy + ry * 0.28;
    ctx.strokeStyle = '#2b2233';
    ctx.fillStyle = '#2b2233';
    ctx.lineWidth = Math.max(1.4, rx * 0.08);
    if (b.action === 'eat') {
      const open = 0.35 + 0.35 * Math.abs(Math.sin(this.time * 10 + b.id));
      ctx.beginPath();
      ctx.ellipse(fx, mouthY, rx * 0.13, ry * 0.11 * open + 1, 0, 0, TAU);
      ctx.fill();
    } else if (b.action === 'flee') {
      ctx.beginPath();
      ctx.ellipse(fx, mouthY + ry * 0.04, rx * 0.1, ry * 0.12, 0, 0, TAU);
      ctx.fill();
    } else {
      ctx.beginPath();
      ctx.moveTo(fx - rx * 0.22, mouthY);
      ctx.quadraticCurveTo(fx, mouthY + ry * (happy ? 0.32 : 0.16), fx + rx * 0.22, mouthY);
      ctx.stroke();
    }
  }

  private drawTree(
    ctx: CanvasRenderingContext2D,
    P: Proj,
    t: Tree,
    tv: TreeVis,
    base: { sx: number; sy: number },
    center: { sx: number; sy: number },
  ): void {
    const wob = Math.sin(this.time * 26 + t.id) * tv.wobble * 0.08;
    const trunkTop = this.project(P, t.x + wob, 1.9, t.z);
    const trunkW = 0.2 * P.s;
    ctx.fillStyle = (() => {
      const g = ctx.createLinearGradient(base.sx - trunkW, 0, base.sx + trunkW, 0);
      g.addColorStop(0, '#7a4f2e');
      g.addColorStop(0.5, '#b07a4c');
      g.addColorStop(1, '#7a4f2e');
      return g;
    })();
    ctx.beginPath();
    ctx.moveTo(base.sx - trunkW, base.sy);
    ctx.lineTo(trunkTop.sx - trunkW * 0.7, trunkTop.sy);
    ctx.lineTo(trunkTop.sx + trunkW * 0.7, trunkTop.sy);
    ctx.lineTo(base.sx + trunkW, base.sy);
    ctx.closePath();
    ctx.fill();

    // fruit that sits behind the canopy first
    const limit = Math.max(1, tv.slots.length);
    const fruitPos: { sx: number; sy: number; sc: number; back: boolean; idx: number }[] = [];
    for (let k = 0; k < limit; k++) {
      const a = (k / limit) * TAU + t.phase;
      const fx = t.x + wob + Math.cos(a) * 1.22;
      const fz = t.z + Math.sin(a) * 1.22;
      const fp = this.project(P, fx, 1.6, fz);
      const sc = tv.slots[k];
      fruitPos.push({ sx: fp.sx, sy: fp.sy, sc, back: Math.sin(a) < 0, idx: k });
    }
    // growing bud on the next free slot
    if (t.fruit < limit) {
      const k = t.fruit;
      const a = (k / limit) * TAU + t.phase;
      const bp = this.project(P, t.x + Math.cos(a) * 1.22, 1.6, t.z + Math.sin(a) * 1.22);
      fruitPos.push({ sx: bp.sx, sy: bp.sy, sc: -t.growth, back: Math.sin(a) < 0, idx: -1 });
    }

    for (const f of fruitPos) if (f.back && f.sc !== 0) this.drawFruit(ctx, f.sx, f.sy, f.sc, P.s);

    // canopy: sphere cluster
    const sats = [
      [0.95, 2.35, 0.25],
      [-0.95, 2.35, 0.25],
      [0, 2.35, 0.95],
      [0, 2.35, -0.95],
    ];
    const cs = (1.2 + 0.05 * Math.sin(this.time * 2 + t.id)) * P.s;
    const cc = this.project(P, t.x + wob, 2.65, t.z);
    const drawSphere = (sx: number, sy: number, r: number) => {
      const g = ctx.createRadialGradient(sx - r * 0.35, sy - r * 0.45, r * 0.1, sx, sy, r * 1.1);
      g.addColorStop(0, '#e4fbc4');
      g.addColorStop(0.35, '#7ccc6f');
      g.addColorStop(1, '#2c7d47');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(sx, sy, r, 0, TAU);
      ctx.fill();
    };
    for (const [dx, dy, dz] of sats) {
      const sp = this.project(P, t.x + wob + dx, 2.5 + dy * 0, t.z + dz);
      drawSphere(sp.sx, sp.sy, cs * 0.72);
    }
    drawSphere(cc.sx, cc.sy, cs);

    for (const f of fruitPos) if (!f.back && f.sc !== 0) this.drawFruit(ctx, f.sx, f.sy, f.sc, P.s);
    void center;
  }

  private drawFruit(ctx: CanvasRenderingContext2D, sx: number, sy: number, sc: number, s: number): void {
    if (sc > 0) {
      const r = 0.2 * s * sc;
      if (r < 0.5) return;
      ctx.strokeStyle = '#6b4a2b';
      ctx.lineWidth = Math.max(1, 0.05 * s);
      ctx.beginPath();
      ctx.moveTo(sx, sy - r * 0.5);
      ctx.lineTo(sx + r * 0.2, sy - r * 1.4);
      ctx.stroke();
      const g = ctx.createRadialGradient(sx - r * 0.35, sy - r * 0.3, r * 0.1, sx, sy, r * 1.1);
      g.addColorStop(0, '#f0ffd8');
      g.addColorStop(0.35, '#8ee04f');
      g.addColorStop(1, '#3f9a33');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(sx, sy, r, 0, TAU);
      ctx.fill();
    } else {
      // pale sprout grows with progress
      const p = -sc;
      const r = (0.06 + 0.12 * p) * s;
      ctx.fillStyle = '#c8f0a8';
      ctx.beginPath();
      ctx.arc(sx, sy, Math.max(1.5, r), 0, TAU);
      ctx.fill();
    }
  }

  private drawSelectionRange(ctx: CanvasRenderingContext2D, P: Proj, world: World, sel: Pick | null): void {
    if (!sel) return;
    let x = 0;
    let z = 0;
    let range = 0;
    if (sel.kind === 'tree') {
      const t = world.trees.find((tr) => tr.id === sel.id);
      if (!t) return;
      x = t.x;
      z = t.z;
      range = TREE_REACH;
    } else {
      const list = sel.kind === 'blue' ? world.blue : world.red;
      const b = list.find((o) => o.id === sel.id);
      if (!b) return;
      const vision = sel.kind === 'blue' ? world.params.blueVision : world.params.redVision;
      x = b.x;
      z = b.z;
      range = vision * b.visionTrait;
    }
    const c = this.project(P, x, 0, z);
    ctx.save();
    ctx.setLineDash([6, 6]);
    ctx.strokeStyle = sel.kind === 'red' ? 'rgba(255,90,95,0.55)' : sel.kind === 'blue' ? 'rgba(63,143,251,0.55)' : 'rgba(100,180,80,0.6)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.ellipse(c.sx, c.sy, range * P.s, range * P.s * P.st, 0, 0, TAU);
    ctx.stroke();
    ctx.restore();
  }

  private drawParticles(ctx: CanvasRenderingContext2D, P: Proj, _dt: number): void {
    for (const p of this.particles) {
      const a = clamp(p.life / p.max, 0, 1);
      if (p.kind === 'ring') {
        const age = 1 - a;
        const r = (0.3 + age * 1.8) * 1;
        ctx.save();
        ctx.globalAlpha = a * 0.8;
        ctx.strokeStyle = p.color;
        ctx.lineWidth = 3;
        const c = this.project(P, p.x, 0, p.z);
        ctx.beginPath();
        ctx.ellipse(c.sx, c.sy, r * P.s, r * P.s * P.st, 0, 0, TAU);
        ctx.stroke();
        ctx.restore();
        continue;
      }
      const c = this.project(P, p.x, p.y, p.z);
      if (p.kind === 'spark') {
        ctx.save();
        ctx.globalAlpha = a;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(c.sx, c.sy, 2.6 + 2 * a, 0, TAU);
        ctx.fill();
        ctx.restore();
      } else if (p.kind === 'puff') {
        ctx.save();
        ctx.globalAlpha = a * 0.5;
        ctx.fillStyle = `rgba(${p.color},1)`;
        ctx.beginPath();
        ctx.arc(c.sx, c.sy, (1 - a) * 12 + 6, 0, TAU);
        ctx.fill();
        ctx.restore();
      } else if (p.kind === 'heart') {
        ctx.save();
        ctx.globalAlpha = a;
        ctx.fillStyle = p.color;
        this.heart(ctx, c.sx, c.sy, 7);
        ctx.restore();
      } else if (p.kind === 'text') {
        ctx.save();
        ctx.globalAlpha = Math.min(1, a * 1.6);
        ctx.font = '800 15px ui-rounded, "SF Pro Rounded", system-ui, sans-serif';
        ctx.textAlign = 'center';
        ctx.lineWidth = 4;
        ctx.strokeStyle = 'rgba(255,255,255,0.95)';
        const rise = (1 - a) * 26;
        ctx.strokeText(p.text ?? '', c.sx, c.sy - rise);
        ctx.fillStyle = p.color;
        ctx.fillText(p.text ?? '', c.sx, c.sy - rise);
        ctx.restore();
      }
    }
  }

  private heart(ctx: CanvasRenderingContext2D, x: number, y: number, s: number): void {
    ctx.beginPath();
    ctx.moveTo(x, y + s * 0.3);
    ctx.bezierCurveTo(x - s, y - s * 0.6, x - s * 0.3, y - s * 1.2, x, y - s * 0.4);
    ctx.bezierCurveTo(x + s * 0.3, y - s * 1.2, x + s, y - s * 0.6, x, y + s * 0.3);
    ctx.fill();
  }
}

