export interface Params {
  // fruit
  fruitGrowth: number; // fraction of one fruit ripened per sim second
  fruitLimit: number; // max fruit hanging per tree
  fruitReturnDelay: number; // seconds after a pick before regrowth starts
  startTrees: number;
  // blue
  blueEnergyUse: number;
  blueSpeed: number;
  blueVision: number;
  blueCopyThreshold: number;
  blueEatTime: number;
  startBlue: number;
  // red
  redEnergyUse: number;
  redSpeed: number;
  redVision: number;
  redContactStrength: number;
  redCopyThreshold: number;
  redPauseTime: number;
  startRed: number;
  // world
  worldSize: number; // garden radius in world units
  seed: number;
}

export const DEFAULT_PARAMS: Params = {
  fruitGrowth: 0.12,
  fruitLimit: 4,
  fruitReturnDelay: 4,
  startTrees: 6,
  blueEnergyUse: 1,
  blueSpeed: 1.2,
  blueVision: 4.5,
  blueCopyThreshold: 78,
  blueEatTime: 2.5,
  startBlue: 24,
  redEnergyUse: 1.3,
  redSpeed: 1.5,
  redVision: 5,
  redContactStrength: 14,
  redCopyThreshold: 60,
  redPauseTime: 3,
  startRed: 8,
  worldSize: 14,
  seed: 4242,
};

export type ParamKey = keyof Params;
export type ParamGroup = 'fruit' | 'blue' | 'red' | 'world';

export interface ParamSpec {
  key: ParamKey;
  label: string;
  min: number;
  max: number;
  step: number;
  unit: string;
  group: ParamGroup;
  /** Needs a fresh garden to take effect (starting counts, size, seed). */
  reset?: boolean;
}

export const PARAM_SPECS: ParamSpec[] = [
  { key: 'fruitGrowth', label: 'Fruit growth speed', min: 0.01, max: 0.3, step: 0.005, unit: '', group: 'fruit' },
  { key: 'fruitLimit', label: 'Fruit limit', min: 1, max: 10, step: 1, unit: 'per tree', group: 'fruit' },
  { key: 'fruitReturnDelay', label: 'Fruit return delay', min: 0, max: 30, step: 0.5, unit: 's', group: 'fruit' },
  { key: 'startTrees', label: 'Starting trees', min: 1, max: 16, step: 1, unit: '', group: 'fruit', reset: true },

  { key: 'blueEnergyUse', label: 'Energy use', min: 0.2, max: 3, step: 0.05, unit: '', group: 'blue' },
  { key: 'blueSpeed', label: 'Speed', min: 0.4, max: 2.4, step: 0.05, unit: '', group: 'blue' },
  { key: 'blueVision', label: 'Vision', min: 1.5, max: 9, step: 0.1, unit: '', group: 'blue' },
  { key: 'blueCopyThreshold', label: 'Copy threshold', min: 45, max: 95, step: 1, unit: 'energy', group: 'blue' },
  { key: 'blueEatTime', label: 'Eating time', min: 0.5, max: 6, step: 0.1, unit: 's', group: 'blue' },
  { key: 'startBlue', label: 'Starting blue blobs', min: 0, max: 80, step: 1, unit: '', group: 'blue', reset: true },

  { key: 'redEnergyUse', label: 'Energy use', min: 0.2, max: 3, step: 0.05, unit: '', group: 'red' },
  { key: 'redSpeed', label: 'Speed', min: 0.4, max: 2.8, step: 0.05, unit: '', group: 'red' },
  { key: 'redVision', label: 'Vision', min: 1.5, max: 9, step: 0.1, unit: '', group: 'red' },
  { key: 'redContactStrength', label: 'Contact strength', min: 4, max: 30, step: 0.5, unit: 'energy', group: 'red' },
  { key: 'redCopyThreshold', label: 'Copy threshold', min: 45, max: 95, step: 1, unit: 'energy', group: 'red' },
  { key: 'redPauseTime', label: 'Pause time', min: 0.2, max: 5, step: 0.1, unit: 's', group: 'red' },
  { key: 'startRed', label: 'Starting red blobs', min: 0, max: 50, step: 1, unit: '', group: 'red', reset: true },

  { key: 'worldSize', label: 'World size', min: 8, max: 24, step: 0.5, unit: 'radius', group: 'world', reset: true },
  { key: 'seed', label: 'Random seed', min: 1, max: 99999, step: 1, unit: '', group: 'world', reset: true },
];

export interface Preset {
  id: string;
  name: string;
  blurb: string;
  params: Partial<Params>;
}

export const PRESETS: Preset[] = [
  {
    id: 'balanced',
    name: 'Balanced garden',
    blurb: 'Default tuning. Blue and red trade the lead in long waves.',
    params: {},
  },
  {
    id: 'fruit-rich',
    name: 'Fruit-rich garden',
    blurb: 'Fast-ripening trees. Blue blobs boom first and red follows.',
    params: { fruitGrowth: 0.2, fruitLimit: 6, fruitReturnDelay: 2, startTrees: 9, startBlue: 30 },
  },
  {
    id: 'red-heavy',
    name: 'Red-heavy garden',
    blurb: 'Crowd of red hunters. Blue dips first, then red crashes.',
    params: { startRed: 24, startBlue: 20, redEnergyUse: 1.5 },
  },
  {
    id: 'fragile',
    name: 'Fragile balance',
    blurb: 'Tight margins. Small nudges tip the garden either way.',
    params: { fruitGrowth: 0.085, fruitReturnDelay: 6, redEnergyUse: 1.45, redContactStrength: 13 },
  },
  {
    id: 'low-fruit',
    name: 'Low-fruit garden',
    blurb: 'Scarce fruit and few trees. Both groups stay small.',
    params: { fruitGrowth: 0.07, fruitLimit: 3, fruitReturnDelay: 8, startTrees: 5, startBlue: 14, startRed: 5, redEnergyUse: 1.0 },
  },
];

/** Presets reset tuning to defaults, then apply their overrides. Seed and garden size are kept. */
export function withPreset(base: Params, preset: Preset): Params {
  return { ...DEFAULT_PARAMS, ...preset.params, seed: base.seed, worldSize: base.worldSize };
}

import type { Sample } from './types';

export interface RunMetrics {
  duration: number;
  peakBlue: number;
  peakBlueAt: number;
  peakRed: number;
  peakRedAt: number;
  peakFruit: number;
  meanFruit: number;
  meanBlueLate: number;
  meanRedLate: number;
  cvBlueLate: number;
  blueExtinctAt: number | null;
  redExtinctAt: number | null;
  blueCycles: number;
  firstBluePeakAt: number | null;
  firstRedPeakAt: number | null;
  /** Late-run swing vs mid-run swing. <0.6 fading, >1.4 growing, else steady. */
  swingTrend: number | null;
}

export interface RunSummary {
  headline: string;
  lines: string[];
  metrics: RunMetrics;
}

export function fmtTime(s: number): string {
  const m = Math.floor(s / 60);
  const sec = Math.floor(s % 60);
  return `${m}:${String(sec).padStart(2, '0')}`;
}

function smooth(vals: number[], win: number): number[] {
  const out: number[] = [];
  for (let i = 0; i < vals.length; i++) {
    let s = 0;
    let n = 0;
    for (let j = Math.max(0, i - win + 1); j <= i; j++) {
      s += vals[j];
      n++;
    }
    out.push(s / n);
  }
  return out;
}

interface Pivot {
  i: number;
  kind: 'peak' | 'trough';
}

/** Zig-zag pivots: a turn only counts once the series has moved `th` away from it. */
function pivots(vals: number[], th: number): Pivot[] {
  const res: Pivot[] = [];
  if (vals.length === 0) return res;
  let trend: 0 | 1 | -1 = 0;
  let hi = vals[0];
  let hiI = 0;
  let lo = vals[0];
  let loI = 0;
  for (let i = 1; i < vals.length; i++) {
    const v = vals[i];
    if (trend >= 0) {
      if (v > hi) {
        hi = v;
        hiI = i;
      }
      if (hi - v >= th) {
        res.push({ i: hiI, kind: 'peak' });
        trend = -1;
        lo = v;
        loI = i;
        continue;
      }
    }
    if (trend <= 0) {
      if (v < lo) {
        lo = v;
        loI = i;
      }
      if (v - lo >= th) {
        res.push({ i: loI, kind: 'trough' });
        trend = 1;
        hi = v;
        hiI = i;
      }
    }
  }
  return res;
}

function mean(xs: number[]): number {
  if (xs.length === 0) return NaN;
  return xs.reduce((a, b) => a + b, 0) / xs.length;
}

function cv(xs: number[]): number {
  const m = mean(xs);
  if (!m) return 0;
  return Math.sqrt(mean(xs.map((x) => (x - m) ** 2))) / m;
}

export function computeMetrics(h: Sample[]): RunMetrics {
  const duration = h.length ? h[h.length - 1].t : 0;
  const blue = h.map((s) => s.blue);
  const red = h.map((s) => s.red);
  const fruit = h.map((s) => s.fruit);
  const n = h.length;
  const third = Math.max(1, Math.floor(n / 3));
  const midB = blue.slice(third, 2 * third);
  const midR = red.slice(third, 2 * third);
  const lateB = blue.slice(2 * third);
  const lateR = red.slice(2 * third);

  let peakBlue = 0;
  let peakBlueAt = 0;
  let peakRed = 0;
  let peakRedAt = 0;
  for (const s of h) {
    if (s.blue > peakBlue) {
      peakBlue = s.blue;
      peakBlueAt = s.t;
    }
    if (s.red > peakRed) {
      peakRed = s.red;
      peakRedAt = s.t;
    }
  }

  const extinct = (arr: number[]): number | null => {
    let seen = false;
    for (let i = 0; i < n; i++) {
      if (arr[i] > 0) seen = true;
      else if (seen) return h[i].t;
    }
    return null;
  };

  const sb = smooth(blue, 10);
  const sr = smooth(red, 10);
  const pb = pivots(sb, Math.max(2, 0.25 * mean(blue))).filter((p) => p.kind === 'peak');
  const pr = pivots(sr, Math.max(1.5, 0.25 * mean(red))).filter((p) => p.kind === 'peak');

  const midCv = (cv(midB) + cv(midR)) / 2;
  const lateCv = (cv(lateB) + cv(lateR)) / 2;

  return {
    duration,
    peakBlue,
    peakBlueAt,
    peakRed,
    peakRedAt,
    peakFruit: Math.max(0, ...fruit),
    meanFruit: mean(fruit),
    meanBlueLate: mean(lateB),
    meanRedLate: mean(lateR),
    cvBlueLate: cv(lateB),
    blueExtinctAt: extinct(blue),
    redExtinctAt: extinct(red),
    blueCycles: pb.length,
    firstBluePeakAt: pb.length ? h[pb[0].i].t : null,
    firstRedPeakAt: pr.length ? h[pr[0].i].t : null,
    swingTrend: midCv > 0.02 ? lateCv / midCv : null,
  };
}

export function summarize(h: Sample[]): RunSummary {
  const m = computeMetrics(h);
  const lines: string[] = [];
  const bothAlive = m.blueExtinctAt === null && m.redExtinctAt === null;

  let headline: string;
  if (m.blueExtinctAt !== null && m.redExtinctAt !== null) {
    headline = `Both groups died out by ${fmtTime(Math.max(m.blueExtinctAt, m.redExtinctAt))}.`;
  } else if (m.redExtinctAt !== null) {
    headline = `Red blobs faded out at ${fmtTime(m.redExtinctAt)}. The world settled into a simpler, blue-only state.`;
  } else if (m.blueExtinctAt !== null) {
    headline = `Blue blobs died out at ${fmtTime(m.blueExtinctAt)}, and the red blobs had nothing left to touch.`;
  } else if (m.duration < 60) {
    headline = 'Run for a minute or two to see the waves.';
  } else if (m.peakBlue < 12) {
    headline = 'Low fruit kept the garden small.';
  } else if (m.swingTrend !== null && m.swingTrend < 0.6) {
    headline = 'The waves are fading. Blue and red are settling toward a steady balance.';
  } else if (m.swingTrend !== null && m.swingTrend > 1.4) {
    headline = 'The swings are growing. Blue and red keep overshooting each other.';
  } else if (m.blueCycles >= 2) {
    headline = 'The garden stayed balanced. Blue and red keep rising and falling out of phase.';
  } else {
    headline = 'Still settling. Give the garden more time.';
  }

  if (m.firstBluePeakAt !== null && m.firstRedPeakAt !== null) {
    const lag = m.firstRedPeakAt - m.firstBluePeakAt;
    if (lag > 3) lines.push(`Blue blobs grew first. Red blobs followed ${Math.round(lag)} s later.`);
    else if (lag < -3) lines.push(`Red blobs peaked first, ${Math.round(-lag)} s before blue.`);
    else lines.push('Blue and red peaked almost together.');
  }
  lines.push(
    `Peaks: ${m.peakBlue} blue at ${fmtTime(m.peakBlueAt)}, ${m.peakRed} red at ${fmtTime(m.peakRedAt)}.`,
  );
  if (m.meanFruit >= 5) lines.push(`Fruit stayed plentiful, averaging ${m.meanFruit.toFixed(1)} on the trees.`);
  else if (m.meanFruit < 1.5) lines.push('Blue blobs ate fruit as fast as it ripened.');
  else lines.push(`Fruit averaged ${m.meanFruit.toFixed(1)} on the trees.`);
  if (bothAlive && m.cvBlueLate < 0.12 && m.meanBlueLate > 5) {
    lines.push(`Blue levelled out near ${Math.round(m.meanBlueLate)}, red near ${Math.round(m.meanRedLate)}.`);
  }
  return { headline, lines, metrics: m };
}

