/** Draws one chart into a W x H area (CSS px). The context must already be scaled for DPR. */
export function drawChart(
  ctx: CanvasRenderingContext2D,
  kind: ChartKind,
  W: number,
  H: number,
  h: Sample[],
  hover: ChartHover | null,
