  flex-direction: column;
}

.topbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px 18px;
  padding: 14px 18px;
  position: sticky;
  top: 0;
  z-index: 5;
  background: rgba(255, 246, 232, 0.92);
  backdrop-filter: blur(6px);
  border-bottom: 2.5px solid var(--ink);
}

.transport {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-left: auto;
}

.chip {
  border: 2px solid var(--ink);
  border-radius: 999px;
  padding: 3px 10px;
  background: #fff;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

.chip.green {
  background: #e4f7d6;
}

.chip.blue {
  background: #dbeeff;
}

.chip.red {
  background: #ffe0df;
}

/* ---------- buttons ---------- */

.btn,
.chip-btn,
.speed {
  font: inherit;
  font-weight: 800;
  color: var(--ink);
  background: #fff;
  border: 2.5px solid var(--ink);
  border-radius: 999px;
  padding: 7px 14px;
  box-shadow: 0 3px 0 var(--ink);
  cursor: pointer;
  transition:
    transform 0.08s ease,
    box-shadow 0.08s ease,
    background 0.15s ease;
}

.btn:hover:not(:disabled),
.chip-btn:hover,
.speed:hover {
  background: #fff7d6;
}

.btn:active:not(:disabled),
.chip-btn:active,
.speed:active {
  transform: translateY(2px);
  box-shadow: 0 1px 0 var(--ink);
}

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.btn.primary {
  background: var(--sun);
}

.btn.primary[aria-pressed='true'] {
  background: #ffb86b;
}

.btn.small {
  padding: 3px 10px;
  font-size: 12px;
  box-shadow: 0 2px 0 var(--ink);
}

.btn.wide {
  width: 100%;
  margin-top: 10px;
}

.speeds {
  display: inline-flex;
  gap: 6px;
  margin-left: 4px;
}

.speed {
  padding: 5px 10px;
  box-shadow: 0 2px 0 var(--ink);
  font-variant-numeric: tabular-nums;
}

.speed.on {
  background: var(--ink);
  color: #fff;
}

/* ---------- layout ---------- */

.layout {
  flex: 1;
  display: grid;
  grid-template-columns: 300px minmax(0, 1fr) 300px;
  gap: 18px;
  padding: 18px;
  align-items: start;
}

.panel {
  display: flex;
  flex-direction: column;
  gap: 16px;
  position: sticky;
  top: 86px;
  max-height: calc(100vh - 104px);
  overflow-y: auto;
  padding-right: 4px;
}

.center {
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-width: 0;
}

@media (max-width: 1180px) {
  .layout {
    grid-template-columns: 1fr 1fr;
  }

  .center {
    grid-column: 1 / -1;
    order: -1;
  }

  .panel {
    position: static;
    max-height: none;
    overflow: visible;
  }
}

@media (max-width: 760px) {
  .layout {
    grid-template-columns: 1fr;
    padding: 12px;
  }

  .chips {
    margin-left: 0;
  }

  .charts {
    grid-template-columns: 1fr !important;
  }
}

/* ---------- cards ---------- */

.card {
  background: var(--card);
  border: 2.5px solid var(--ink);
  border-radius: var(--radius);
  box-shadow: 4px 4px 0 var(--ink);
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
}

.card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
}

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  font-size: 12px;
  font-weight: 800;
}

.lg {
  padding: 2px 9px;
  border-radius: 999px;
  border: 2px solid var(--ink);
  background: #fff;
}

.lg.green {
  background: #e4f7d6;
}

.lg.blue {
  background: #dbeeff;
}

.lg.red {
  background: #ffe0df;
}

.dot {
  display: inline-block;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 2px solid var(--ink);
  margin-right: 6px;
  vertical-align: -1px;
}

.dot.blue {
  background: var(--blue);
}

.dot.red {
  background: var(--red);
}

/* ---------- garden stage ---------- */

.stage {
  position: relative;
  height: min(70vh, 640px);
  min-height: 380px;
  border: 2.5px solid var(--ink);
  border-radius: 26px;
  overflow: hidden;
  box-shadow: 4px 4px 0 var(--ink);
  background: #fff6e8;
}

.garden {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  cursor: grab;
}

.stage-hint {
  position: absolute;
  left: 12px;
  bottom: 10px;
  padding: 4px 10px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.85);
  border: 2px solid var(--ink);
  font-size: 12px;
  font-weight: 700;
  pointer-events: none;
}

/* ---------- charts ---------- */

.charts {
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr);
  gap: 16px;
}

.chart {
  width: 100%;
  min-width: 0;
}

.chart canvas {
  display: block;
}

/* ---------- controls ---------- */

.controls {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.preset-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.chip-btn {
  padding: 5px 11px;
  font-size: 12px;
  box-shadow: 0 2px 0 var(--ink);
}

.group {
  --accent: var(--ink);
}

.group h2 {
  display: flex;
  align-items: center;
  gap: 8px;
}

.group h2::before {
  content: '';
  width: 12px;
  height: 12px;
  border-radius: 4px;
  background: var(--accent);
  border: 2px solid var(--ink);
}

.slider,
.field {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-weight: 700;
}

.field-top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
  font-size: 13px;
}

.field-top output {
  font-variant-numeric: tabular-nums;
  font-weight: 800;
  white-space: nowrap;
}

.slider input[type='range'] {
  width: 100%;
  margin: 0;
  accent-color: var(--accent);
  cursor: pointer;
}

.field input[type='number'] {
  font: inherit;
  font-weight: 800;
  border: 2px solid var(--ink);
  border-radius: 10px;
  padding: 5px 8px;
  width: 100%;
}

.pending {
  margin-left: 6px;
  padding: 1px 7px;
  border-radius: 999px;
  border: 2px solid var(--ink);
  background: var(--sun);
  font-size: 11px;
  font-style: normal;
  font-weight: 800;
  white-space: nowrap;
}

/* ---------- inspector ---------- */

.inspector {
  gap: 8px;
}

.insp-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.insp-head h2 {
  display: flex;
  align-items: center;
}

.insp-row {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  font-size: 13px;
}

.insp-row span {
  color: var(--muted);
  font-weight: 700;
}

.insp-row strong {
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.insp-bar {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.track {
  height: 12px;
  border-radius: 999px;
  border: 2px solid var(--ink);
  background: #f4efe6;
  overflow: hidden;
}

.fill {
  height: 100%;
  transition: width 0.25s ease;
}

/* ---------- summary ---------- */

.summary .headline {
  font-size: 17px;
  font-weight: 900;
}

.summary ul {
  padding-left: 18px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-weight: 600;
}

