.chip-btn,
.speed {
  font: inherit;
  font-weight: 800;
  color: var(--ink);
  background: #fff;
  border: 2.5px solid var(--ink);
  border-radius: 999px;
  padding: 7px 14px;
  box-shadow: 0 3px 0 var(--ink);
  cursor: pointer;
  transition:
    transform 0.08s ease,
    box-shadow 0.08s ease,
    background 0.15s ease;
}

.btn:hover:not(:disabled),
.chip-btn:hover,
.speed:hover {
  background: #fff7d6;
}

.btn:active:not(:disabled),
.chip-btn:active,
.speed:active {
  transform: translateY(2px);
  box-shadow: 0 1px 0 var(--ink);
}

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.btn.primary {
  background: var(--sun);
}

.btn.primary[aria-pressed='true'] {
  background: #ffb86b;
}

.btn.small {
  padding: 3px 10px;
  font-size: 12px;
  box-shadow: 0 2px 0 var(--ink);
}

.btn.wide {
  width: 100%;
  margin-top: 10px;
}

.speeds {
  display: inline-flex;
  gap: 6px;
  margin-left: 4px;
}

.speed {
  padding: 5px 10px;
  box-shadow: 0 2px 0 var(--ink);
  font-variant-numeric: tabular-nums;
}

.speed.on {
  background: var(--ink);
  color: #fff;
}

/* ---------- layout ---------- */

.layout {
  flex: 1;
  display: grid;
  grid-template-columns: 300px minmax(0, 1fr) 300px;
  gap: 18px;
  padding: 18px;
  align-items: start;
}

.panel {
  display: flex;
  flex-direction: column;
  gap: 16px;
  position: sticky;
  top: 86px;
  max-height: calc(100vh - 104px);
  overflow-y: auto;
  padding-right: 4px;
}

.center {
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-width: 0;
}

@media (max-width: 1180px) {
  .layout {
    grid-template-columns: 1fr 1fr;
  }

  .center {
    grid-column: 1 / -1;
    order: -1;
  }

  .panel {
    position: static;
    max-height: none;
    overflow: visible;
  }
}

@media (max-width: 760px) {
  .layout {
    grid-template-columns: 1fr;
    padding: 12px;
  }

  .chips {
    margin-left: 0;
  }

  .charts {
    grid-template-columns: 1fr !important;
  }
}

