.card {
  background: var(--card);
  border: 2.5px solid var(--ink);
  border-radius: var(--radius);
  box-shadow: 4px 4px 0 var(--ink);
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
}

.card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
}

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  font-size: 12px;
  font-weight: 800;
}

.lg {
  padding: 2px 9px;
  border-radius: 999px;
  border: 2px solid var(--ink);
  background: #fff;
}

.lg.green {
  background: #e4f7d6;
}

.lg.blue {
  background: #dbeeff;
}

.lg.red {
  background: #ffe0df;
}

.dot {
  display: inline-block;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 2px solid var(--ink);
  margin-right: 6px;
  vertical-align: -1px;
}

.dot.blue {
  background: var(--blue);
}

.dot.red {
  background: var(--red);
}

/* ---------- garden stage ---------- */

.stage {
  position: relative;
  height: min(70vh, 640px);
  min-height: 380px;
  border: 2.5px solid var(--ink);
  border-radius: 26px;
  overflow: hidden;
  box-shadow: 4px 4px 0 var(--ink);
  background: #fff6e8;
}

.garden {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  cursor: grab;
}

.stage-hint {
  position: absolute;
  left: 12px;
  bottom: 10px;
  padding: 4px 10px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.85);
  border: 2px solid var(--ink);
  font-size: 12px;
  font-weight: 700;
  pointer-events: none;
}

/* ---------- charts ---------- */

.charts {
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr);
  gap: 16px;
}

.chart {
  width: 100%;
  min-width: 0;
}

.chart canvas {
  display: block;
}

/* ---------- controls ---------- */

.controls {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.preset-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.chip-btn {
  padding: 5px 11px;
  font-size: 12px;
  box-shadow: 0 2px 0 var(--ink);
}

.group {
  --accent: var(--ink);
}

.group h2 {
  display: flex;
  align-items: center;
  gap: 8px;
}

.group h2::before {
  content: '';
  width: 12px;
  height: 12px;
  border-radius: 4px;
  background: var(--accent);
  border: 2px solid var(--ink);
}

.slider,
.field {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-weight: 700;
}

.field-top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
  font-size: 13px;
}

.field-top output {
  font-variant-numeric: tabular-nums;
  font-weight: 800;
  white-space: nowrap;
}

.slider input[type='range'] {
  width: 100%;
  margin: 0;
  accent-color: var(--accent);
  cursor: pointer;
}

.field input[type='number'] {
  font: inherit;
  font-weight: 800;
  border: 2px solid var(--ink);
  border-radius: 10px;
  padding: 5px 8px;
  width: 100%;
}

.pending {
  margin-left: 6px;
  padding: 1px 7px;
  border-radius: 999px;
  border: 2px solid var(--ink);
  background: var(--sun);
  font-size: 11px;
  font-style: normal;
  font-weight: 800;
  white-space: nowrap;
}

/* ---------- inspector ---------- */

.inspector {
  gap: 8px;
}

.insp-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.insp-head h2 {
  display: flex;
  align-items: center;
}

.insp-row {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  font-size: 13px;
}

.insp-row span {
  color: var(--muted);
  font-weight: 700;
}

.insp-row strong {
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.insp-bar {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.track {
  height: 12px;
  border-radius: 999px;
  border: 2px solid var(--ink);
  background: #f4efe6;
  overflow: hidden;
}

.fill {
  height: 100%;
  transition: width 0.25s ease;
}

/* ---------- summary ---------- */

.summary .headline {
  font-size: 17px;
  font-weight: 900;
}

.summary ul {
  padding-left: 18px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-weight: 600;
}

