import { chromium } from 'playwright-core';

const URL = 'http://127.0.0.1:9379/';
const OUT = new URL('.', import.meta.url).pathname;

const browser = await chromium.launch({
  executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  headless: true,
});
const page = await browser.newPage({ viewport: { width: 1440, height: 980 }, deviceScaleFactor: 1 });

const errors = [];
page.on('console', (msg) => {
  if (msg.type() === 'error' || msg.type() === 'warning') errors.push(`[${msg.type()}] ${msg.text()}`);
});
page.on('pageerror', (err) => errors.push(`[pageerror] ${err.message}`));

await page.goto(URL, { waitUntil: 'networkidle' });
await page.waitForSelector('canvas.garden');

const title = await page.title();
const h1 = await page.locator('h1').allInnerTexts();
console.log('title:', JSON.stringify(title));
console.log('h1:', JSON.stringify(h1));

await page.screenshot({ path: `${OUT}shot-0-initial.png` });

await page.getByRole('button', { name: 'Play' }).click();
await page.waitForTimeout(8000);
const chips = await page.locator('.chips .chip').allInnerTexts();
console.log('chips after 8s:', chips);
await page.screenshot({ path: `${OUT}shot-1-playing.png`, fullPage: true });

await page.getByRole('button', { name: 'Show' }).click();
await page.waitForTimeout(1500);
await page.screenshot({ path: `${OUT}shot-2-traits.png`, fullPage: true });

// Hover over the timeline to make sure tooltips draw without errors.
const timeline = page.locator('canvas[aria-label="Population timeline"]');
const box = await timeline.boundingBox();
if (box) {
  await page.mouse.move(box.x + box.width * 0.6, box.y + box.height * 0.5);
  await page.waitForTimeout(300);
}

// Click the garden center to try selecting something.
const garden = page.locator('canvas.garden');
const gb = await garden.boundingBox();
if (gb) {
  for (let i = 0; i < 25; i++) {
    const x = gb.x + gb.width * (0.3 + 0.4 * ((i * 37) % 100) / 100);
    const y = gb.y + gb.height * (0.3 + 0.4 * ((i * 53) % 100) / 100);
    await page.mouse.click(x, y);
    const insp = await page.locator('.inspector h2').first().innerText().catch(() => '');
    if (insp && !/Inspector/.test(insp)) {
      console.log('selected:', insp, 'at attempt', i);
      break;
    }
  }
  await page.waitForTimeout(600);
  await page.screenshot({ path: `${OUT}shot-3-selected.png`, fullPage: true });
}

await page.getByRole('button', { name: 'Pause' }).click().catch(() => {});
await page.waitForTimeout(300);
console.log('errors:', errors.length ? errors : 'none');

await browser.close();

