import { chromium } from 'playwright-core';

const APP_URL = 'http://127.0.0.1:9379/';
const OUT = new URL('.', import.meta.url).pathname;

const browser = await chromium.launch({
  executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  headless: true,
});
const page = await browser.newPage({ viewport: { width: 1440, height: 980 }, deviceScaleFactor: 1 });

const errors = [];
page.on('console', (msg) => {
  if (msg.type() === 'error' || msg.type() === 'warning') errors.push(`[${msg.type()}] ${msg.text()}`);
});
page.on('pageerror', (err) => errors.push(`[pageerror] ${err.message}`));
page.on('response', (res) => {
  if (res.status() >= 400) errors.push(`[http ${res.status()}] ${res.url()}`);
});

await page.goto(APP_URL, { waitUntil: 'networkidle' });
await page.waitForSelector('canvas.garden');

console.log('title:', JSON.stringify(await page.title()));
console.log('h1:', JSON.stringify(await page.locator('h1').allInnerTexts()));

// Pending-garden flow: changing a reset-only value must flag the controls.
const startBlue = page.locator('label.slider', { hasText: 'Starting blue blobs' }).locator('input[type=range]');
await startBlue.fill('30');
console.log('pending tag after startBlue change:', await page.locator('.pending').count());
await page.getByRole('button', { name: 'Start fresh garden' }).click();
console.log('pending tag after fresh garden:', await page.locator('.pending').count());

// Presets and randomize should rebuild cleanly.
await page.getByRole('button', { name: 'Fruit-rich garden' }).click();
await page.waitForTimeout(300);
await page.getByRole('button', { name: 'Randomize' }).click();
await page.waitForTimeout(300);
console.log('chips after preset+randomize:', await page.locator('.chips .chip').allInnerTexts());

await page.getByRole('button', { name: 'Balanced garden' }).click();
await page.getByRole('button', { name: 'Play' }).click();
await page.waitForTimeout(9000);
console.log('chips after 9s:', await page.locator('.chips .chip').allInnerTexts());
await page.screenshot({ path: `${OUT}shot-1-playing.png` });

await page.getByRole('button', { name: 'Show' }).click();
await page.waitForTimeout(800);
await page.locator('.card', { hasText: 'Trait trends' }).screenshot({ path: `${OUT}shot-2-traits.png` });

// Hover the timeline to exercise tooltips.
const timeline = page.locator('canvas[aria-label="Population timeline"]');
const tb = await timeline.boundingBox();
if (tb) {
  await page.mouse.move(tb.x + tb.width * 0.6, tb.y + tb.height * 0.5);
  await page.waitForTimeout(200);
  await timeline.screenshot({ path: `${OUT}shot-2b-timeline-hover.png` });
}

// Hunt for a blue blob with the inspector.
const garden = page.locator('canvas.garden');
const gb = await garden.boundingBox();
let found = null;
for (let i = 0; i < 80 && !found; i++) {
  const x = gb.x + gb.width * (0.25 + 0.5 * (((i * 37) % 101) / 100));
  const y = gb.y + gb.height * (0.25 + 0.5 * (((i * 53) % 101) / 100));
  await page.mouse.click(x, y);
  const head = await page.locator('.inspector h2').first().innerText().catch(() => '');
  if (/blob/i.test(head)) found = head;
}
console.log('inspected:', found);
await page.waitForTimeout(400);
if (found) {
  await page.locator('.inspector').screenshot({ path: `${OUT}shot-3-inspector.png` });
}
await page.screenshot({ path: `${OUT}shot-4-selected.png` });

await page.getByRole('button', { name: 'Pause' }).click();
console.log('errors:', errors.length ? errors : 'none');

await browser.close();

