import { chromium } from 'playwright-core';

const browser = await chromium.launch({
  executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  headless: true,
});
const page = await browser.newPage({ viewport: { width: 1440, height: 980 } });
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
await page.goto('http://127.0.0.1:9379/', { waitUntil: 'networkidle' });
await page.waitForSelector('canvas.garden');

const label = () => page.locator('.transport button').first().innerText();
const time = () => page.locator('.chips .chip').first().innerText();

console.log('start:', await label(), await time());
await page.getByRole('button', { name: 'Play' }).click();
await page.waitForTimeout(1200);
console.log('after click play:', await label(), await time());
await page.keyboard.press('Space');
await page.waitForTimeout(300);
console.log('after Space (should pause):', await label(), await time());
await page.keyboard.press('Space');
await page.waitForTimeout(1200);
console.log('after Space (should play):', await label(), await time());
await page.keyboard.press('Space');
const t0 = await time();
await page.keyboard.press('s');
await page.waitForTimeout(200);
console.log('step s:', t0, '->', await time());
console.log('errors:', errors.length ? errors : 'none');
await browser.close();

